    [0, 0, 0, 5, 0, 0, 0, 5, 0, 0, 5, 0]
]

# Analyze the grid
print("Grid dimensions:", len(grid), "x", len(grid[0]))
print("Values in grid:", set(val for row in grid for val in row))

# Count 5s per row
for i, row in enumerate(grid):
    print(f"Row {i}: {row.count(5)} fives")

# Count 5s per column
for j in range(len(grid[0])):
    col_count = sum(grid[i][j] for i in range(len(grid)))
    print(f"Column {j}: {col_count} fives")

# Check for symmetry
def check_horizontal_symmetry(grid):
    width = len(grid[0])
    for i, row in enumerate(grid):
        for j in range(width // 2):
            if row[j] != row[width - 1 - j]:
                return False
    return True

def check_vertical_symmetry(grid):
    height = len(grid)
    for i in range(height // 2):
        for j in range(len(grid[0])):
            if grid[i][j] != grid[height - 1 - i][j]:
                return False
    return True

print("Horizontal symmetry:", check_horizontal_symmetry(grid))
print("Vertical symmetry:", check_vertical_symmetry(grid))

# Look for patterns in columns
# Check if each column is symmetric within itself
for j in range(len(grid[0])):
    column = [grid[i][j] for i in range(len(grid))]
    print(f"Column {j}: {column}")

